    { id: "spells", label: "Loading spell defs", total: Object.keys(SPELL_DEFS).length },
    { id: "items", label: "Loading item catalog", total: Object.keys(ITEM_CATALOG).length },
    { id: "affixes", label: "Loading affix defs", total: affixEntries.length },
    { id: "loot", label: "Loading loot tables", total: Object.keys(LOOT_TABLES).length },
    { id: "deities", label: "Loading deity defs", total: Object.keys(DEITY_DEFS).length },
    { id: "gems", label: "Loading gem defs", total: Object.keys(GEM_DEFS).length },
    {
      id: "food",
      label: "Loading nutrition defs",
      total: Object.keys(NUTRITION_BY_SIZE).length + Object.keys(CORPSE_DEFS).length,
    },
    { id: "applyPayloads", label: "Loading apply payloads", total: APPLY_PAYLOADS.length },
    { id: "effects", label: "Loading effect defs", total: EFFECT_DEFS.length },
    {
      id: "usePayloads",
      label: "Loading use payloads",
      total: useItemPayloadKeys.length + USE_ITEM_MATCHER_PAYLOADS.length,
    },
    { id: "materialReactions", label: "Loading material reactions", total: MATERIAL_REACTION_RULES.length },
    { id: "validate", label: "Validating data", total: 1 },
  ];
  const overallTotal = datasets.reduce((sum, ds) => sum + ds.total, 0);
  return { datasets, overallTotal };
}

/**
 * @param {{ onProgress?: (progress: DataLoadProgress) => void }} [opts]
 * @returns {{ completed: number, overallTotal: number }}
 */
export function loadGameData(opts = {}) {
  const onProgress = typeof opts.onProgress === "function" ? opts.onProgress : null;
  const plan = getGameDataLoadPlan();
  let completed = 0;

  /**
   * @param {DataLoadPlanItem} ds
   * @param {number} processed
   */
  function emit(ds, processed) {
    if (!onProgress) return;
    onProgress({
      phase: "data",
      dataset: ds.id,
      label: ds.label,
      processed,
      total: ds.total,
      completed,
      overallTotal: plan.overallTotal,
    });
  }

  for (const ds of plan.datasets) {
    emit(ds, 0);

    if (ds.id === "monsters") {
      const allMonsters = getAllMonsters();
      for (let i = 0; i < allMonsters.length; i++) {
        void allMonsters[i];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "spells") {
      const keys = Object.keys(SPELL_DEFS);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        void SPELL_DEFS[key];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "items") {
      const keys = Object.keys(ITEM_CATALOG);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        void ITEM_CATALOG[key];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "affixes") {
      const entries = listAffixEntries();
      for (let i = 0; i < entries.length; i++) {
        void entries[i];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "loot") {
      const keys = Object.keys(LOOT_TABLES);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        void LOOT_TABLES[key];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "deities") {
      const keys = Object.keys(DEITY_DEFS);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        void DEITY_DEFS[key];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "gems") {
      const keys = Object.keys(GEM_DEFS);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        void GEM_DEFS[key];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "food") {
      const nKeys = Object.keys(NUTRITION_BY_SIZE);
      let processed = 0;
      for (let i = 0; i < nKeys.length; i++) {
        const key = nKeys[i];
        void NUTRITION_BY_SIZE[key];
        completed++;
        processed++;
        emit(ds, processed);
      }
      const cKeys = Object.keys(CORPSE_DEFS);
      for (let i = 0; i < cKeys.length; i++) {
        const key = cKeys[i];
        void CORPSE_DEFS[key];
        completed++;
        processed++;
        emit(ds, processed);
      }
      continue;
    }

    if (ds.id === "applyPayloads") {
      for (let i = 0; i < APPLY_PAYLOADS.length; i++) {
        void APPLY_PAYLOADS[i];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "effects") {
      for (let i = 0; i < EFFECT_DEFS.length; i++) {
        void EFFECT_DEFS[i];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "usePayloads") {
      let processed = 0;
      const itemPayloadKeys = Object.keys(USE_ITEM_PAYLOADS);
      for (let i = 0; i < itemPayloadKeys.length; i++) {
        const key = itemPayloadKeys[i];
        void USE_ITEM_PAYLOADS[key];
        completed++;
        processed++;
        emit(ds, processed);
      }
      for (let i = 0; i < USE_ITEM_MATCHER_PAYLOADS.length; i++) {
        void USE_ITEM_MATCHER_PAYLOADS[i];
        completed++;
        processed++;
        emit(ds, processed);
      }
      continue;
    }

    if (ds.id === "materialReactions") {
      for (let i = 0; i < MATERIAL_REACTION_RULES.length; i++) {
        void MATERIAL_REACTION_RULES[i];
        completed++;
        emit(ds, i + 1);
      }
      continue;
    }

    if (ds.id === "validate") {
      validateAll({
        ITEM_CATALOG,
        AMMO_DEFS,
        AFFIXES: listAffixEntries(),
        MATERIAL_REACTION_RULES,
        MATERIAL_REACTION_OUTCOME_IDS,
        APPLY_PAYLOADS,
        USE_ITEM_PAYLOADS,
        USE_ITEM_MATCHER_PAYLOADS,
        EFFECT_DEFS,
        EFFECT_OPERATION_IDS,
        MONSTERS: getAllMonsters(),
      });
      completed++;
      emit(ds, 1);
    }
  }

